// Banco de preguntas tipo examen de «Fundamentos de redes» (CCST Networking, dominio 1). Clave = nivel de práctica.
import { op, vs, rel, ord } from './_ayuda.mjs';

export default {
  /* ============================================ 1 · Qué es una red */
  1: [
    op('Un técnico instala en una oficina un equipo al que se conectan por cable 24 computadoras de la misma red, y que entrega cada trama solo al equipo de destino. ¿Qué equipo instaló?', ['Un switch', 'Un router', 'Un módem', 'Un servidor'], 0, 'Conectar por cable a los equipos de una misma red y entregar cada trama a su destinatario es la función del switch. El router une redes distintas; el módem adapta la señal del proveedor; el servidor es un dispositivo final.'),
    op('¿Qué dispositivo necesita una oficina para que sus computadoras puedan comunicarse con redes distintas a la suya, por ejemplo Internet?', ['Un router', 'Un hub', 'Un punto de acceso', 'Un repetidor'], 0, 'Solo el router conecta redes diferentes y decide el camino entre ellas. El hub, el repetidor y el punto de acceso trabajan dentro de una misma red.'),
    op('En el inventario de una empresa aparecen: 40 laptops, 3 impresoras de red, 2 switches, 1 router y 6 cámaras IP. ¿Cuántos son dispositivos finales?', ['49', '40', '43', '52'], 0, 'Son finales los equipos donde empiezan o terminan los datos: 40 laptops + 3 impresoras + 6 cámaras = 49. Los 2 switches y el router son dispositivos intermedios.'),
    op('Una clínica quiere que las tabletas de los médicos se conecten a la red sin cables mientras recorren las habitaciones. ¿Qué dispositivo intermedio debe instalar?', ['Puntos de acceso inalámbricos', 'Más switches de capa 2', 'Un servidor DHCP adicional', 'Un firewall'], 0, 'El punto de acceso es el que une a los clientes wifi con la red cableada. Los switches solo dan puertos de cable; DHCP reparte direcciones y el firewall filtra, pero ninguno da cobertura inalámbrica.'),
    op('Una empresa tiene oficinas en Tijuana, Puebla y Cancún, enlazadas mediante circuitos contratados a un operador. ¿Qué tipo de red forman esos enlaces?', ['WAN', 'LAN', 'CAN', 'PAN'], 0, 'Enlazar sitios en ciudades distintas con servicios de un proveedor es una WAN. LAN y CAN no salen de un edificio o de un predio, y la PAN rodea a una persona.'),
    op('Un hospital tiene cinco edificios dentro del mismo terreno, unidos con fibra óptica propia. ¿Cómo se clasifica esa red?', ['CAN', 'MAN', 'WAN', 'WLAN'], 0, 'Varios edificios cercanos de una misma organización, con enlaces propios, forman una red de campus. La MAN cubre una ciudad y la WAN usa enlaces de un operador entre lugares lejanos.'),
    op('Un usuario imprime desde su teléfono en una impresora portátil usando Bluetooth, a un metro de distancia. ¿Qué tipo de red se formó?', ['PAN', 'WLAN', 'LAN', 'MAN'], 0, 'Dos dispositivos de una persona enlazados por Bluetooth a muy corta distancia son una PAN. La WLAN usa wifi (802.11) a través de un punto de acceso.'),
    op('¿Cuál es la diferencia principal entre una LAN y una WLAN?', ['El medio: la WLAN usa ondas de radio en lugar de cable', 'El alcance: la WLAN cubre ciudades enteras', 'La WLAN no necesita direcciones IP', 'La LAN solo existe en casas'], 0, 'Las dos cubren un área local; cambia el medio. La WLAN no tiene mayor alcance (al contrario) y sus equipos usan direcciones IP igual que los cableados.'),
    op('Un proveedor de servicios tiende un anillo de fibra que conecta a todos sus clientes de una misma ciudad. ¿Qué tipo de red es?', ['MAN', 'CAN', 'PAN', 'LAN'], 0, 'Una red que cubre el área de una ciudad es metropolitana. La CAN se limita a los edificios de una organización dentro de un predio.'),
    op('¿Qué característica distingue normalmente a una WAN de una LAN?', ['La WAN usa enlaces de un proveedor de servicios', 'La WAN es siempre más rápida', 'La WAN no usa routers', 'La WAN solo conecta dos equipos'], 0, 'Para cubrir grandes distancias se alquilan enlaces a operadores. Lo habitual es que la WAN sea más lenta y más cara que la LAN, y los routers son justo los equipos que la conectan.'),
    op('El área de Recursos Humanos publica las políticas internas en un sitio web al que solo se entra desde la red de la empresa con la cuenta de empleado. ¿Dónde está publicado?', ['En la intranet', 'En Internet', 'En una extranet', 'En una red PAN'], 0, 'Un sitio de uso exclusivo del personal es parte de la intranet. Sería extranet si se abriera a proveedores o clientes, e Internet si fuera público.'),
    op('Una aseguradora permite a los talleres mecánicos asociados entrar a un sistema de la empresa para registrar reparaciones. ¿Cómo se llama ese tipo de acceso?', ['Extranet', 'Intranet', 'Red de campus', 'Internet pública'], 0, 'Dar acceso controlado a organizaciones externas asociadas es una extranet. La intranet es solo para el personal propio.'),
    op('En una topología en estrella con un switch central, se desconecta por accidente el cable de la computadora 3. ¿Qué equipos pierden la conexión?', ['Solo la computadora 3', 'Todas las computadoras', 'La 3 y las que están junto a ella', 'Ninguna: el switch busca otro camino'], 0, 'En la estrella cada equipo tiene su propio cable hasta el centro, así que el fallo de un cable afecta solo a ese equipo. No hay camino alterno para un equipo con un único cable.'),
    op('Una empresa quiere la máxima redundancia entre sus 4 routers principales: que cada uno tenga enlace directo con todos los demás. ¿Cuántos enlaces necesita?', ['6', '4', '8', '12'], 0, 'En una malla completa hacen falta n × (n − 1) ÷ 2 enlaces: 4 × 3 ÷ 2 = 6. Con 4 enlaces solo se formaría un anillo, y 12 sería contar cada enlace dos veces.'),
    op('¿Qué topología describe mejor a Internet, donde hay varios caminos entre muchos puntos, pero no todos están unidos con todos?', ['Malla parcial', 'Bus', 'Estrella simple', 'Punto a punto'], 0, 'Internet tiene múltiples rutas redundantes sin llegar a unir cada red con todas las demás: es una malla parcial.'),
    op('Un ingeniero le pide a un técnico: «Mira el diagrama y dime qué subred usa el piso 3 y cuál es su puerta de enlace». ¿Qué diagrama necesita el técnico?', ['El de topología lógica', 'El de topología física', 'El plano eléctrico del edificio', 'El diagrama de rack'], 0, 'Las subredes, direcciones IP y puertas de enlace se documentan en la topología lógica. La física y el diagrama de rack muestran ubicaciones, cables y puertos.'),
    op('Un técnico debe cambiar un cable y necesita saber a qué puerto del panel de parcheo llega la roseta 2-14. ¿Qué documento consulta?', ['El diagrama de topología física', 'El diagrama de topología lógica', 'La tabla de direcciones IP', 'La lista de usuarios'], 0, 'El recorrido real de los cables, las rosetas y los puertos pertenece a la documentación física.'),
    op('En una red doméstica, el aparato que entrega el proveedor ofrece wifi, cuatro puertos de cable y salida a Internet. ¿Qué afirmación es correcta?', ['Reúne en una caja las funciones de router, switch y punto de acceso', 'Es únicamente un switch', 'Es únicamente un punto de acceso', 'Es un servidor de archivos'], 0, 'El equipo doméstico integra varias funciones: enruta hacia Internet, conmuta entre sus puertos de cable y da cobertura wifi (y suele incluir un firewall básico).'),
    op('Un dispositivo antiguo recibe una señal por un puerto y la repite por todos los demás, sin leer ninguna dirección. ¿Qué es?', ['Un hub', 'Un switch', 'Un router', 'Un firewall'], 0, 'El hub es un repetidor multipuerto: no examina direcciones. El switch lee la MAC y el router la IP antes de reenviar.'),
    op('Un sensor de temperatura de una bodega envía sus lecturas por la red a un servidor cada minuto. ¿Qué tipo de dispositivo es el sensor?', ['Un dispositivo final (IoT)', 'Un dispositivo intermedio', 'Un medio de red', 'Un protocolo'], 0, 'El sensor es el origen de los datos: es un dispositivo final, de la familia del Internet de las cosas. No reenvía tráfico de otros.'),
    vs('¿Cuáles **dos** son dispositivos intermedios?', ['Router', 'Impresora de red', 'Punto de acceso inalámbrico', 'Teléfono IP', 'Servidor web'], [0, 2], 'El router y el punto de acceso reenvían tráfico de otros equipos. La impresora, el teléfono IP y el servidor son origen o destino de los datos.'),
    vs('¿Cuáles **tres** son dispositivos finales?', ['Cámara IP', 'Switch', 'Laptop', 'Servidor de archivos', 'Firewall'], [0, 2, 3], 'La cámara, la laptop y el servidor generan o reciben datos. El switch y el firewall solo los dejan pasar (o los bloquean).'),
    vs('¿Cuáles **dos** redes son propiedad de la organización que las usa y no requieren contratar enlaces a un operador?', ['LAN', 'WAN', 'CAN', 'MAN del proveedor de cable', 'Internet'], [0, 2], 'La LAN y la red de campus se montan con infraestructura propia. La WAN y la MAN de un operador dependen de enlaces contratados, e Internet no pertenece a nadie en particular.'),
    vs('¿Cuáles **dos** afirmaciones sobre la topología en estrella son correctas?', ['Todos los equipos se conectan a un punto central', 'Un corte en un cable deja sin servicio a toda la red', 'El equipo central es un punto único de fallo', 'Cada equipo tiene enlace directo con todos los demás', 'Usa un único cable compartido'], [0, 2], 'En la estrella todo converge en un equipo central, y si ese equipo falla se cae todo. El corte de un cable solo afecta a un equipo; los enlaces todos-con-todos son de la malla completa y el cable compartido es del bus.'),
    vs('¿Cuáles **dos** datos aparecen en un diagrama de topología **física**?', ['El rack y el puerto donde está conectado cada equipo', 'La subred de cada VLAN', 'El tipo y la longitud de los cables', 'Las direcciones IP de las interfaces', 'El protocolo de enrutamiento'], [0, 2], 'La topología física documenta ubicaciones, puertos y cableado. Subredes, direcciones y protocolos son información lógica.'),
    rel('Relaciona cada situación con el tipo de red.', [
      ['Un ratón Bluetooth y una laptop', 'PAN'], ['Los equipos cableados de un despacho', 'LAN'], ['Los pabellones de un campus con fibra propia', 'CAN'], ['Las oficinas de una empresa en dos países', 'WAN'],
    ], 'Una persona (PAN), un lugar (LAN), varios edificios vecinos (CAN) y distancias entre países (WAN).', ['MAN']),
    rel('Relaciona cada dispositivo con su función principal.', [
      ['Switch', 'Conecta equipos de una misma red por cable'], ['Router', 'Conecta redes distintas'], ['Punto de acceso', 'Conecta equipos por wifi a la red cableada'], ['Firewall', 'Filtra el tráfico permitido y el bloqueado'],
    ], 'Cada dispositivo intermedio tiene una tarea: conmutar dentro de la red, enrutar entre redes, dar acceso inalámbrico o filtrar.'),
    rel('Relaciona cada término con quién puede acceder.', [
      ['Internet', 'Cualquier persona'], ['Intranet', 'Solo el personal de la organización'], ['Extranet', 'Socios externos autorizados'],
    ], 'La diferencia entre los tres términos es el público al que se abre la red.'),
    ord('Ordena estas redes de la que cubre **menos** área a la que cubre **más**.', ['PAN', 'LAN', 'CAN', 'MAN', 'WAN'], 'Persona, lugar, campus, ciudad y distancias entre ciudades o países.'),
  ],

  /* ============================================ 2 · Modelos de capas */
  2: [
    op('Un técnico descubre que un cable de red está aplastado y el puerto del switch no enciende. ¿En qué capa del modelo OSI está la falla?', ['Capa 1 · Física', 'Capa 2 · Enlace de datos', 'Capa 3 · Red', 'Capa 4 · Transporte'], 0, 'Un cable dañado y la ausencia de señal son problemas de la capa física. Las capas superiores no pueden trabajar si la 1 no funciona.'),
    op('Un equipo tiene configurada por error una dirección IP de otra subred y no alcanza a su puerta de enlace. ¿Qué capa del modelo OSI está mal configurada?', ['Capa 3 · Red', 'Capa 1 · Física', 'Capa 5 · Sesión', 'Capa 7 · Aplicación'], 0, 'El direccionamiento IP pertenece a la capa de red. El cable (capa 1) puede estar perfecto y aun así no haber comunicación.'),
    op('¿Qué capa del modelo OSI se encarga de elegir el camino para que un paquete llegue a otra red?', ['Red', 'Transporte', 'Enlace de datos', 'Sesión'], 0, 'El enrutamiento entre redes es tarea de la capa 3. Enlace de datos solo entrega dentro de una misma red, y transporte se ocupa de las aplicaciones de los extremos.'),
    op('¿Qué capa del modelo OSI entrega los datos a la aplicación correcta mediante números de puerto?', ['Transporte', 'Red', 'Aplicación', 'Presentación'], 0, 'Los puertos se definen en la capa 4. La capa de aplicación usa el servicio, pero no es la que separa las conversaciones por puerto.'),
    op('¿Qué capa del modelo OSI se ocupa del cifrado, la compresión y el formato de los datos?', ['Presentación', 'Sesión', 'Aplicación', 'Transporte'], 0, 'La capa 6 «presenta» los datos en un formato que el otro extremo entienda. Sesión administra el diálogo y aplicación ofrece el servicio.'),
    op('¿Qué capa del modelo OSI establece, mantiene y termina el diálogo entre dos aplicaciones?', ['Sesión', 'Presentación', 'Red', 'Física'], 0, 'Controlar la conversación es la función de la capa 5.'),
    op('¿En qué capa del modelo OSI trabaja un switch convencional y qué dirección utiliza para reenviar?', ['Capa 2, dirección MAC', 'Capa 3, dirección IP', 'Capa 1, ninguna dirección', 'Capa 4, número de puerto'], 0, 'El switch lee la MAC de destino de la trama: capa 2. Leer la IP es propio del router, y no leer nada, del hub.'),
    op('¿En qué capa del modelo OSI trabaja un router y qué dirección utiliza para decidir?', ['Capa 3, dirección IP', 'Capa 2, dirección MAC', 'Capa 4, número de puerto', 'Capa 7, nombre de dominio'], 0, 'El router decide la salida mirando la IP de destino del paquete: capa 3.'),
    op('¿Cuántas capas tiene el modelo TCP/IP que usa el examen CCST?', ['4', '5', '7', '3'], 0, 'Acceso a la red, Internet, Transporte y Aplicación. Siete son las de OSI.'),
    op('¿Qué capa del modelo TCP/IP reúne las funciones de las capas física y de enlace de datos de OSI?', ['Acceso a la red', 'Internet', 'Transporte', 'Aplicación'], 0, 'TCP/IP agrupa las capas 1 y 2 de OSI en la capa de acceso a la red.'),
    op('El protocolo IP pertenece a la capa de Red del modelo OSI. ¿Cómo se llama esa misma capa en el modelo TCP/IP?', ['Internet', 'Acceso a la red', 'Enlace', 'Sesión'], 0, 'La capa 3 de OSI equivale a la capa de Internet en TCP/IP. «Sesión» no existe como capa propia en TCP/IP.'),
    op('¿Por qué un técnico puede cambiar el cable de cobre de un enlace por fibra óptica sin reconfigurar el navegador de los usuarios?', ['Porque cada capa es independiente de las demás', 'Porque la fibra usa las mismas señales que el cobre', 'Porque el navegador trabaja en la capa física', 'Porque las capas superiores se desactivan'], 0, 'El modelo de capas permite cambiar la tecnología de una capa (aquí la física) sin afectar a las otras. La fibra usa luz, no electricidad, y el navegador trabaja en la capa de aplicación.'),
    op('¿Qué es un protocolo de red?', ['Un conjunto de reglas que acuerdan los equipos para comunicarse', 'Un tipo de cable', 'Un programa antivirus', 'Un dispositivo que une redes'], 0, 'Un protocolo define el formato, el orden y el significado de los mensajes. No es un objeto físico ni un programa de seguridad.'),
    op('Un usuario no puede enviar correo. El técnico comprueba que el cable funciona, que la dirección IP es correcta y que hay respuesta al hacer ping al servidor de correo. ¿En qué capas es más probable que esté el problema?', ['En las capas superiores (transporte a aplicación)', 'En la capa física', 'En la capa de enlace de datos', 'En la capa de red'], 0, 'El ping demuestra que las capas 1, 2 y 3 funcionan. Queda revisar lo de arriba: un puerto bloqueado, el servicio de correo o la configuración de la aplicación.'),
    op('Un técnico aplica el método «de abajo hacia arriba» para diagnosticar una falla. ¿Qué comprueba primero?', ['El cable y la luz de enlace', 'La configuración del navegador', 'El servidor DNS', 'El número de puerto de la aplicación'], 0, 'De abajo arriba significa empezar por la capa 1: conexión física y señal. El navegador y DNS están en la capa más alta.'),
    op('¿Qué organización publicó el modelo OSI?', ['ISO', 'IEEE', 'IETF', 'Cisco'], 0, 'El modelo OSI es de la Organización Internacional de Normalización (ISO). El IEEE publica estándares como Ethernet (802.3) y wifi (802.11), y el IETF, los protocolos de Internet.'),
    op('¿Qué organización publica los estándares 802.3 (Ethernet) y 802.11 (wifi)?', ['IEEE', 'ISO', 'IETF', 'ICANN'], 0, 'Los estándares de la familia 802 son del IEEE. El IETF publica los RFC de protocolos como IP y TCP.'),
    op('¿Cuál de estos protocolos pertenece a la capa de Transporte?', ['UDP', 'IP', 'HTTP', 'Ethernet'], 0, 'UDP y TCP son los protocolos de transporte. IP es de red, HTTP de aplicación y Ethernet de enlace de datos.'),
    op('Un switch «de capa 3» se diferencia de un switch convencional en que…', ['además puede enrutar paquetes entre redes', 'no usa direcciones MAC', 'solo funciona con fibra', 'trabaja en la capa de aplicación'], 0, 'El switch multicapa conmuta por MAC como cualquier switch y, además, enruta por IP como un router.'),
    op('Dos fabricantes distintos producen tarjetas de red que funcionan juntas sin problema. ¿Qué lo hace posible?', ['Que las dos siguen los mismos estándares abiertos', 'Que usan el mismo sistema operativo', 'Que tienen la misma dirección MAC', 'Que se configuran con la misma contraseña'], 0, 'La interoperabilidad se logra porque todos implementan los mismos estándares en cada capa. Dos tarjetas nunca deben compartir dirección MAC.'),
    vs('¿Cuáles **dos** capas del modelo OSI corresponden a la capa de Acceso a la red de TCP/IP?', ['Física', 'Red', 'Enlace de datos', 'Transporte', 'Sesión'], [0, 2], 'Acceso a la red equivale a las capas 1 y 2 de OSI. La capa de red equivale a Internet.'),
    vs('¿Cuáles **dos** protocolos trabajan en la capa de Internet del modelo TCP/IP?', ['IPv6', 'TCP', 'ICMP', 'DNS', 'Ethernet'], [0, 2], 'IP (en sus dos versiones) e ICMP son de la capa de Internet. TCP es de transporte, DNS de aplicación y Ethernet de acceso a la red.'),
    vs('¿Cuáles **tres** protocolos pertenecen a la capa de Aplicación?', ['HTTP', 'TCP', 'DNS', 'DHCP', 'IP'], [0, 2, 3], 'HTTP, DNS y DHCP son servicios de aplicación. TCP es de transporte e IP de red.'),
    vs('¿Cuáles **dos** son ventajas de usar un modelo de capas?', ['Facilita localizar en qué parte está una falla', 'Hace innecesarias las direcciones IP', 'Permite que equipos de distintos fabricantes trabajen juntos', 'Elimina la necesidad de cables', 'Duplica la velocidad de la red'], [0, 2], 'Las capas ordenan el diagnóstico y fijan reglas comunes para todos los fabricantes. No cambian la velocidad ni eliminan direcciones o cables.'),
    vs('¿Cuáles **dos** elementos pertenecen a la capa física?', ['El conector RJ-45', 'La dirección MAC', 'La señal de luz en una fibra', 'El número de puerto', 'La dirección IP'], [0, 2], 'Conectores y señales son de capa 1. La MAC es de capa 2, la IP de capa 3 y los puertos de capa 4.'),
    rel('Relaciona cada protocolo con su capa del modelo OSI.', [
      ['HTTP', 'Capa 7 · Aplicación'], ['TCP', 'Capa 4 · Transporte'], ['IP', 'Capa 3 · Red'], ['Ethernet', 'Capa 2 · Enlace de datos'],
    ], 'HTTP es un servicio de aplicación, TCP transporta de extremo a extremo, IP direcciona entre redes y Ethernet entrega dentro de la red local.', ['Capa 1 · Física']),
    rel('Relaciona cada capa de TCP/IP con las capas OSI que abarca.', [
      ['Aplicación', 'Capas 5, 6 y 7'], ['Transporte', 'Capa 4'], ['Internet', 'Capa 3'], ['Acceso a la red', 'Capas 1 y 2'],
    ], 'TCP/IP condensa las tres capas superiores en una y las dos inferiores en otra.'),
    rel('Relaciona cada síntoma con la capa OSI donde hay que buscar primero.', [
      ['El puerto del switch no tiene luz de enlace', 'Capa 1'], ['El equipo tiene una IP de otra subred', 'Capa 3'], ['Los nombres de los sitios no se resuelven', 'Capa 7'],
    ], 'Sin luz no hay señal (capa 1); una IP equivocada es direccionamiento (capa 3); resolver nombres es DNS, un servicio de aplicación (capa 7).', ['Capa 5']),
    ord('Ordena las capas del modelo OSI de la **7 a la 1** (de arriba hacia abajo).', ['Aplicación', 'Presentación', 'Sesión', 'Transporte', 'Red', 'Enlace de datos', 'Física'], 'De arriba abajo: Aplicación, Presentación, Sesión, Transporte, Red, Enlace de datos y Física.'),
  ],

  /* ============================================ 3 · Encapsulación */
  3: [
    op('¿Cómo se llama la PDU de la capa de enlace de datos?', ['Trama', 'Paquete', 'Segmento', 'Bits'], 0, 'En la capa 2 la unidad es la trama. El paquete es de capa 3, el segmento de capa 4 y los bits de capa 1.'),
    op('¿Cómo se llama la PDU de la capa de red?', ['Paquete', 'Trama', 'Segmento', 'Datos'], 0, 'La capa 3 trabaja con paquetes, que llevan las direcciones IP.'),
    op('¿Cómo se llama el proceso de añadir un encabezado en cada capa a medida que los datos bajan por el modelo?', ['Encapsulación', 'Desencapsulación', 'Segmentación', 'Enrutamiento'], 0, 'Encapsular es envolver los datos con el encabezado de cada capa al enviar. Desencapsular es quitarlo al recibir; segmentar es cortar los datos en trozos.'),
    op('Un servidor recibe una trama. ¿Qué capa es la primera en quitar su encabezado?', ['Enlace de datos', 'Red', 'Transporte', 'Aplicación'], 0, 'Al recibir se sube por el modelo: tras convertir las señales en bits, la capa 2 comprueba y retira el encabezado y el tráiler de la trama.'),
    op('¿Qué capa añade, además de un encabezado, un tráiler al final de la PDU?', ['Enlace de datos', 'Red', 'Transporte', 'Sesión'], 0, 'La trama lleva al final el campo FCS para detectar errores. Las demás capas solo añaden encabezado.'),
    op('¿Para qué sirve el campo FCS del tráiler de una trama Ethernet?', ['Para detectar si la trama se dañó durante la transmisión', 'Para indicar el puerto de destino', 'Para cifrar el contenido', 'Para numerar los bytes'], 0, 'El FCS es un código de comprobación: si al recalcularlo no coincide, la trama se descarta. No corrige, no cifra y no numera.'),
    op('¿Cuántos bits tiene una dirección MAC?', ['48', '32', '64', '128'], 0, 'La MAC tiene 48 bits (12 dígitos hexadecimales). 32 bits tiene una dirección IPv4 y 128 una IPv6.'),
    op('En la dirección MAC `00:1A:2B:3C:4D:5E`, ¿qué identifican los tres primeros bytes (`00:1A:2B`)?', ['Al fabricante de la tarjeta', 'A la red a la que pertenece', 'Al país del equipo', 'Al número de puerto'], 0, 'Los primeros 24 bits son el identificador del fabricante (OUI); los otros 24 distinguen a la tarjeta. La MAC no contiene información de red ni de ubicación.'),
    op('PC1 (red A) envía un paquete a PC2 (red B) a través de un router. ¿Qué dirección MAC de destino pone PC1 en la trama?', ['La de la interfaz del router en la red A', 'La de PC2', 'La de la interfaz del router en la red B', 'La del switch al que está conectada'], 0, 'PC1 solo puede entregar tramas dentro de su red: se la manda a su puerta de enlace, que es la interfaz del router en la red A. El switch no es destinatario de la trama.'),
    op('Un router recibe una trama, extrae el paquete y lo reenvía por otra interfaz. ¿Qué direcciones MAC lleva la nueva trama?', ['Origen: la interfaz de salida del router; destino: el siguiente equipo del camino', 'Las mismas que traía la trama original', 'Origen: el equipo que envió el paquete; destino: el router', 'No lleva direcciones MAC'], 0, 'El router crea una trama nueva para la red de salida, con su propia MAC como origen y la del siguiente salto (o del destino final, si está en esa red) como destino.'),
    op('Un paquete viaja de un cliente a un servidor pasando por dos routers, sin NAT. ¿Cuántas veces cambia la dirección IP de destino durante el viaje?', ['Ninguna', 'Una', 'Dos', 'Tres'], 0, 'Las direcciones IP identifican los extremos y se conservan en todo el trayecto. Lo que se rehace en cada red es la trama.'),
    op('En ese mismo viaje a través de dos routers, ¿cuántas tramas distintas se crean en total?', ['Tres', 'Una', 'Dos', 'Cuatro'], 0, 'Hay tres redes en el camino: cliente–router 1, router 1–router 2 y router 2–servidor. En cada una viaja una trama distinta.'),
    op('¿Qué dirección usa un switch de capa 2 para decidir por qué puerto reenvía una trama?', ['La MAC de destino', 'La IP de destino', 'El puerto TCP de destino', 'La MAC de origen'], 0, 'El switch reenvía según la MAC de destino. La MAC de origen la usa para aprender en qué puerto está cada equipo, no para decidir la salida.'),
    op('¿Qué capa añade los puertos de origen y destino durante la encapsulación?', ['Transporte', 'Red', 'Enlace de datos', 'Física'], 0, 'Los puertos van en el encabezado de TCP o UDP, en la capa 4.'),
    op('Un analizador de tráfico muestra `Src: 192.168.1.20, Dst: 172.16.5.9`. ¿A qué encabezado pertenecen esos datos?', ['Al encabezado IP (capa 3)', 'Al encabezado de la trama (capa 2)', 'Al encabezado TCP (capa 4)', 'Al tráiler de la trama'], 0, 'Son direcciones IPv4, que viajan en el encabezado del paquete. La trama lleva direcciones MAC y TCP lleva puertos.'),
    op('Un analizador de tráfico muestra `Src Port: 51522, Dst Port: 53`. ¿A qué encabezado pertenecen esos datos?', ['Al de la capa de transporte', 'Al de la capa de red', 'Al de la capa de enlace de datos', 'Al de la capa física'], 0, 'Los puertos son de la capa de transporte. El 53 indica, además, que es una consulta DNS.'),
    op('¿Cómo escribe Windows una dirección MAC en la salida de `ipconfig /all`?', ['`00-1A-2B-3C-4D-5E`', '`001a.2b3c.4d5e`', '`00:1a:2b:3c:4d:5e`', '`1A2B.3C4D`'], 0, 'Windows separa los seis bytes con guiones. Los tres bloques con puntos son de Cisco IOS, y los dos puntos, de Linux y macOS.'),
    op('¿Qué dirección MAC de destino lleva una trama de broadcast, la que deben recibir todos los equipos de la red local?', ['`ff:ff:ff:ff:ff:ff`', '`00:00:00:00:00:00`', '`255.255.255.255`', '`01:00:5e:00:00:01`'], 0, 'La MAC de broadcast tiene los 48 bits en 1. `255.255.255.255` es el broadcast de IPv4, no una dirección MAC.'),
    op('¿Por qué un equipo necesita una dirección IP además de su dirección MAC?', ['Porque la MAC solo sirve dentro de la red local y la IP permite llegar a otras redes', 'Porque la MAC se repite en todos los equipos', 'Porque la IP es más corta', 'Porque los switches solo entienden direcciones IP'], 0, 'La MAC identifica al siguiente equipo dentro de la red actual; la IP identifica al destino final en cualquier red. Las MAC no se repiten y los switches trabajan justamente con ellas.'),
    op('¿Cómo se llama la PDU de la capa de transporte cuando se usa UDP?', ['Datagrama', 'Segmento', 'Trama', 'Celda'], 0, 'Con TCP la PDU es el segmento; con UDP se le llama datagrama.'),
    op('Un técnico captura esta información de una trama que sale de PC1 hacia un servidor de Internet. ¿A quién pertenece la MAC de destino?', ['A la puerta de enlace de PC1', 'Al servidor `93.184.216.34`', 'Al servidor DNS', 'Al switch'], 0, 'El destino IP está en otra red, así que la trama se entrega al router de salida. La MAC de un servidor de Internet nunca aparece en la red local.',
      { codigo: `Ethernet II  Src: 00:1a:2b:11:22:33   Dst: 00:1c:58:aa:bb:01
Internet Protocol  Src: 192.168.1.20  Dst: 93.184.216.34
Transmission Control Protocol  Src Port: 50210  Dst Port: 443` }),
    vs('¿Cuáles **dos** datos están en el encabezado de la capa de red?', ['Dirección IP de origen', 'Dirección MAC de destino', 'Dirección IP de destino', 'Puerto de destino', 'Código FCS'], [0, 2], 'El paquete lleva las dos direcciones IP. Las MAC y el FCS son de la trama; el puerto es del segmento.'),
    vs('¿Cuáles **dos** cosas cambian cada vez que un paquete cruza un router (sin NAT)?', ['La MAC de origen de la trama', 'La IP de origen', 'La MAC de destino de la trama', 'El puerto de destino', 'La IP de destino'], [0, 2], 'El router sustituye la trama completa, con nuevas MAC de origen y destino. Las IP y los puertos se conservan de extremo a extremo.'),
    vs('¿Cuáles **dos** afirmaciones sobre la desencapsulación son correctas?', ['Ocurre en el equipo que recibe', 'Añade un encabezado en cada capa', 'Cada capa quita su propio encabezado y pasa el resto hacia arriba', 'Empieza en la capa de aplicación', 'Solo la realizan los routers'], [0, 2], 'Al recibir, se sube por el modelo retirando encabezados. Añadir encabezados es encapsular, y eso empieza en la capa de aplicación del emisor.'),
    vs('¿Cuáles **tres** identificadores intervienen para que un dato llegue a la aplicación correcta de un equipo de otra red?', ['Dirección MAC', 'Dirección IP', 'Número de puerto', 'Nombre del fabricante', 'Número de serie'], [0, 1, 2], 'La MAC lleva la trama en cada tramo, la IP lleva el paquete hasta el equipo de destino y el puerto lo entrega a la aplicación.'),
    vs('¿Cuáles **dos** formatos representan correctamente una dirección MAC?', ['`00:1a:2b:3c:4d:5e`', '`192.168.1.1`', '`001a.2b3c.4d5e`', '`00:1g:2b:3c:4d:5e`', '`fe80::1`'], [0, 2], 'Una MAC son 12 dígitos hexadecimales (0–9 y a–f). La opción con «g» no es hexadecimal; las otras dos son direcciones IPv4 e IPv6.'),
    rel('Relaciona cada PDU con lo que añade su encabezado.', [
      ['Segmento', 'Puertos de origen y destino'], ['Paquete', 'Direcciones IP de origen y destino'], ['Trama', 'Direcciones MAC de origen y destino'],
    ], 'Cada capa añade su propio tipo de dirección: puertos en transporte, IP en red y MAC en enlace de datos.', ['Nombres de dominio']),
    rel('Relaciona cada identificador con la pregunta que responde.', [
      ['Número de puerto', '¿A qué aplicación va?'], ['Dirección IP', '¿A qué equipo de destino final va?'], ['Dirección MAC', '¿A qué equipo de esta red se entrega ahora?'],
    ], 'Puerto para la aplicación, IP para el destino final y MAC para el siguiente salto dentro de la red local.'),
    ord('Ordena los encabezados de una trama tal como viajan por el cable, **del primero al último**.', ['Encabezado de trama (MAC)', 'Encabezado IP', 'Encabezado TCP', 'Datos de la aplicación', 'Tráiler (FCS)'], 'La trama envuelve al paquete, el paquete al segmento y el segmento a los datos; el FCS cierra la trama.'),
  ],

  /* ============================================ 4 · Rendimiento */
  4: [
    op('Un proveedor ofrece un plan de «500 megas». ¿A qué medida se refiere esa cifra?', ['Al ancho de banda en Mbps', 'Al throughput garantizado en MB/s', 'A la latencia en ms', 'A la capacidad de almacenamiento en MB'], 0, 'Los planes se anuncian por su capacidad máxima en megabits por segundo. No es una velocidad garantizada ni está en megabytes.'),
    op('¿Qué término describe la capacidad máxima teórica de un enlace?', ['Ancho de banda', 'Throughput', 'Goodput', 'Jitter'], 0, 'El ancho de banda es lo que el enlace puede transportar como máximo. Throughput y goodput son medidas de lo que realmente pasa.'),
    op('¿Qué término describe los datos útiles que recibe la aplicación, descontando encabezados y retransmisiones?', ['Goodput', 'Ancho de banda', 'Latencia', 'Throughput'], 0, 'El goodput es la parte del throughput que aprovecha la aplicación. Siempre es igual o menor que el throughput.'),
    op('¿Cuál de estas relaciones es siempre verdadera?', ['El throughput es menor o igual que el ancho de banda', 'El throughput es mayor que el ancho de banda', 'El goodput es mayor que el throughput', 'La latencia es igual al ancho de banda'], 0, 'No puede pasar más de lo que el enlace admite, y lo útil no puede superar a lo transferido.'),
    op('Un usuario dice: «Pago 100 megas y el navegador descarga a 12 megas». ¿Qué le explica el técnico?', ['Que 100 Mbps equivalen a 12.5 MB/s: son unidades distintas', 'Que el proveedor le entrega solo el 12 % del servicio', 'Que su tarjeta de red está dañada', 'Que debe cambiar de navegador'], 0, 'El plan está en megabits y el navegador muestra megabytes. 100 ÷ 8 = 12.5 MB/s: la conexión rinde lo contratado.'),
    op('¿Cuántos bits tiene un byte?', ['8', '4', '10', '16'], 0, 'Un byte son 8 bits. De ahí sale el factor 8 entre Mbps y MB/s.'),
    op('Un enlace transfiere a 24 Mbps. ¿Cuánto tarda en descargar un archivo de 90 MB?', ['30 segundos', '3.75 segundos', '240 segundos', '11 segundos'], 0, '24 Mbps ÷ 8 = 3 MB/s, y 90 MB ÷ 3 MB/s = 30 s. El resultado de 3.75 sale de dividir 90 entre 24 sin convertir las unidades.'),
    op('¿A cuántos Mbps equivale 1 Gbps?', ['1,000 Mbps', '100 Mbps', '8 Mbps', '1,024,000 Mbps'], 0, 'Giga es mil veces mega: 1 Gbps = 1,000 Mbps.'),
    op('¿Qué mide el tiempo que muestra cada línea de respuesta del comando `ping`?', ['El retardo de ida y vuelta', 'El ancho de banda del enlace', 'El tamaño del archivo', 'El número de saltos'], 0, '`ping` mide cuánto tarda la solicitud en ir y la respuesta en volver: la latencia de ida y vuelta, en milisegundos.'),
    op('Un técnico obtiene esta salida. ¿Qué problema muestra?', ['Pérdida de paquetes del 50 %', 'Jitter alto sin pérdidas', 'Latencia baja y estable', 'Fallo de resolución de nombres'], 0, 'Dos de las cuatro solicitudes no recibieron respuesta: se perdió la mitad. Los tiempos de las que sí llegaron son estables, así que el jitter no es lo anormal; y el destino es una IP, no interviene DNS.',
      { codigo: `C:\\> ping 10.20.30.1
Respuesta desde 10.20.30.1: bytes=32 tiempo=8ms TTL=64
Tiempo de espera agotado para esta solicitud.
Respuesta desde 10.20.30.1: bytes=32 tiempo=9ms TTL=64
Tiempo de espera agotado para esta solicitud.

    Paquetes: enviados = 4, recibidos = 2, perdidos = 2 (50% perdidos)` }),
    op('Un técnico obtiene esta salida hacia el servidor de videoconferencias. ¿Qué medida es la más preocupante?', ['El jitter: los tiempos varían mucho entre un paquete y otro', 'La pérdida de paquetes', 'El ancho de banda', 'El TTL'], 0, 'No se pierde ningún paquete, pero la latencia oscila entre 12 y 210 ms. Esa variación es jitter, y es lo que entrecorta el audio y el video en vivo.',
      { codigo: `Respuesta desde 172.16.8.4: bytes=32 tiempo=12ms TTL=58
Respuesta desde 172.16.8.4: bytes=32 tiempo=210ms TTL=58
Respuesta desde 172.16.8.4: bytes=32 tiempo=15ms TTL=58
Respuesta desde 172.16.8.4: bytes=32 tiempo=187ms TTL=58
    Paquetes: enviados = 4, recibidos = 4, perdidos = 0 (0% perdidos)` }),
    op('¿Qué tipo de aplicación sufre más con una latencia alta?', ['Una llamada de voz sobre IP', 'El envío de un correo', 'La copia nocturna de un respaldo', 'La descarga de una actualización'], 0, 'En una conversación en vivo, el retraso se nota de inmediato. El correo, los respaldos y las descargas solo tardan un poco más.'),
    op('Una empresa duplica el ancho de banda de su enlace por satélite, pero las videollamadas siguen con el mismo retraso. ¿Por qué?', ['Porque el ancho de banda no reduce la latencia de propagación', 'Porque el proveedor no aplicó el cambio', 'Porque las videollamadas usan TCP', 'Porque falta un servidor DNS'], 0, 'El retraso lo causa la distancia que recorre la señal. Más capacidad permite pasar más datos a la vez, pero no hace que lleguen antes.'),
    op('¿Qué herramienta necesita que un equipo actúe como servidor y otro como cliente para medir el throughput entre ambos?', ['iPerf', 'Una prueba de velocidad en línea', '`ping`', '`ipconfig`'], 0, 'iPerf mide entre dos extremos que el técnico elige e instala. La prueba de velocidad usa servidores de Internet ya existentes.'),
    op('Un técnico quiere comprobar si el proveedor de internet entrega la velocidad contratada. ¿Qué herramienta es la más directa?', ['Una prueba de velocidad contra un servidor de Internet', 'iPerf entre dos computadoras de la oficina', '`nslookup`', 'El comando `arp -a`'], 0, 'La prueba de velocidad mide el tramo hacia Internet, que es el que entrega el proveedor. iPerf entre dos equipos internos mide solo la LAN.'),
    op('Una prueba de velocidad por wifi da 40 Mbps; la misma prueba con cable, en el mismo lugar, da 290 Mbps. ¿Dónde está el cuello de botella?', ['En el tramo inalámbrico', 'En el proveedor de internet', 'En el servidor de la prueba', 'En el servidor DNS'], 0, 'Lo único que cambió entre las dos mediciones es el wifi. El proveedor y el servidor de la prueba son los mismos en ambas.'),
    op('Entre dos sedes hay un enlace de 20 Mbps. En cada sede, la LAN es de 1 Gbps. ¿Cuál es el throughput máximo al copiar un archivo de una sede a la otra?', ['20 Mbps', '1 Gbps', '510 Mbps', '1,020 Mbps'], 0, 'El enlace más lento del camino limita toda la transferencia: es el cuello de botella. Las velocidades no se promedian ni se suman.'),
    op('¿Qué provoca en una conexión TCP una pérdida de paquetes del 5 %?', ['Retransmisiones que reducen el throughput', 'Un aumento del ancho de banda', 'El cambio automático a UDP', 'Que el enlace cambie de dirección IP'], 0, 'TCP vuelve a enviar lo perdido y, además, reduce su ritmo de envío al detectar pérdidas. El resultado es una transferencia más lenta.'),
    op('Con iPerf en modo UDP, ¿qué dos medidas se obtienen además del throughput?', ['Jitter y pérdida de paquetes', 'Dirección MAC y fabricante', 'Servidor DNS y puerta de enlace', 'Temperatura y voltaje'], 0, 'En modo UDP iPerf informa de la variación del retardo y del porcentaje de datagramas perdidos, justo lo que importa para voz y video.'),
    op('Una oficina con un enlace de 50 Mbps tiene 25 usuarios descargando al mismo tiempo. ¿Qué throughput le toca aproximadamente a cada uno si se reparte por igual?', ['2 Mbps', '50 Mbps', '25 Mbps', '1,250 Mbps'], 0, 'El enlace se comparte: 50 ÷ 25 = 2 Mbps por usuario. Es el efecto de la congestión sobre el throughput individual.'),
    vs('¿Cuáles **dos** medidas se expresan en milisegundos?', ['Latencia', 'Ancho de banda', 'Jitter', 'Pérdida de paquetes', 'Goodput'], [0, 2], 'Latencia y jitter son tiempos. El ancho de banda y el goodput se miden en bits por segundo, y la pérdida en porcentaje.'),
    vs('¿Cuáles **dos** aplicaciones son las más sensibles al jitter?', ['Voz sobre IP', 'Correo electrónico', 'Videoconferencia en vivo', 'Descarga de archivos', 'Respaldo en la nube'], [0, 2], 'La voz y el video en tiempo real necesitan que los paquetes lleguen a ritmo constante. Las demás toleran que los datos lleguen a ritmo irregular.'),
    vs('¿Cuáles **dos** afirmaciones sobre una prueba de velocidad en línea son correctas?', ['Mide el camino entre tu equipo y un servidor de Internet', 'Indica exactamente en qué cable está la falla', 'Informa de las velocidades de bajada y de subida', 'Requiere instalar un servidor propio', 'Solo funciona con IPv6'], [0, 2], 'La prueba mide el tramo completo hasta Internet y da bajada, subida y latencia. No señala dónde está el problema ni necesita un servidor propio.'),
    vs('¿Cuáles **dos** causas pueden producir latencia alta?', ['Una gran distancia entre origen y destino', 'El color del conector', 'La congestión, que hace esperar a los paquetes en cola', 'Un monitor de baja resolución', 'El nombre de la red wifi'], [0, 2], 'La latencia suma el tiempo de propagación (distancia) y la espera en colas (congestión), además del procesamiento en cada equipo.'),
    vs('¿Cuáles **dos** conversiones son correctas?', ['80 Mbps = 10 MB/s', '80 Mbps = 640 MB/s', '1 Gbps = 125 MB/s', '1 Gbps = 8,000 MB/s', '8 Mbps = 64 MB/s'], [0, 2], 'Para pasar de bits a bytes se divide entre 8: 80 ÷ 8 = 10 y 1,000 ÷ 8 = 125. Las opciones falsas multiplican en vez de dividir.'),
    rel('Relaciona cada término con su definición.', [
      ['Ancho de banda', 'Capacidad máxima del enlace'], ['Throughput', 'Datos que realmente pasan'], ['Latencia', 'Tiempo que tarda un dato en llegar'], ['Jitter', 'Variación del retardo'],
    ], 'Capacidad, medida real, tiempo de viaje y variación de ese tiempo.', ['Porcentaje de paquetes que no llegan']),
    rel('Relaciona cada necesidad con la herramienta adecuada.', [
      ['Verificar la velocidad contratada con el proveedor', 'Prueba de velocidad en línea'], ['Medir el throughput entre dos equipos de la LAN', 'iPerf'], ['Medir la latencia y la pérdida hacia un equipo', 'ping'],
    ], 'La prueba de velocidad mide hacia Internet, iPerf entre dos extremos elegidos y ping da latencia y pérdida.', ['nslookup']),
    rel('Relaciona cada unidad con lo que mide.', [
      ['Gbps', 'Velocidad de un enlace'], ['GB', 'Tamaño de un archivo'], ['ms', 'Retardo'],
    ], 'Los bits por segundo miden velocidad, los bytes miden tamaño y los milisegundos miden tiempo.', ['Intensidad de la señal']),
    ord('Ordena estas velocidades de **menor a mayor**.', ['500 kbps', '8 Mbps', '100 Mbps', '1 Gbps', '10 Gbps'], 'Kilo, mega y giga son factores de mil: 500 kbps es medio megabit, y 1 Gbps son 1,000 Mbps.'),
  ],

  /* ============================================ 5 · Transporte */
  5: [
    op('¿Cuál es la función principal de un número de puerto?', ['Identificar a qué aplicación del equipo se entregan los datos', 'Identificar al equipo dentro de la red local', 'Identificar al fabricante de la tarjeta', 'Indicar la velocidad del enlace'], 0, 'El puerto separa las conversaciones de las distintas aplicaciones de un mismo equipo. Identificar al equipo es tarea de las direcciones IP y MAC.'),
    op('¿Cuál es el número de puerto más alto que existe?', ['65,535', '1,023', '49,151', '4,094'], 0, 'El puerto es un número de 16 bits: de 0 a 65,535. El 1,023 es el último de los bien conocidos y el 49,151 el último de los registrados.'),
    op('¿En qué rango están los puertos «bien conocidos»?', ['0 a 1023', '1024 a 49151', '49152 a 65535', '0 a 255'], 0, 'Los servicios clásicos (web, correo, DNS, SSH) usan puertos de 0 a 1023.'),
    op('Un servidor web recibe a la vez peticiones de 300 clientes en su puerto 443. ¿Cómo distingue una conversación de otra?', ['Por la combinación de IP y puerto de origen de cada cliente', 'Por la dirección MAC de cada cliente', 'Asignando un puerto de destino distinto a cada cliente', 'Por el orden de llegada'], 0, 'Cada conexión queda identificada por el par de sockets. Aunque el destino sea el mismo, la IP y el puerto de origen de cada cliente son distintos. La MAC de los clientes no llega al servidor a través de Internet.'),
    op('¿Qué protocolo de transporte establece una conexión antes de enviar datos?', ['TCP', 'UDP', 'IP', 'ICMP'], 0, 'TCP es orientado a conexión. UDP envía sin aviso previo; IP e ICMP no son protocolos de transporte.'),
    op('¿Cuál es el segundo mensaje del saludo de tres vías de TCP?', ['SYN-ACK', 'SYN', 'ACK', 'FIN'], 0, 'El cliente envía SYN, el servidor contesta SYN-ACK y el cliente cierra con ACK.'),
    op('¿Qué bandera de TCP indica que un equipo quiere cerrar la conexión de forma ordenada?', ['FIN', 'SYN', 'RST', 'URG'], 0, 'FIN significa «no tengo más datos que enviar». RST corta la conexión de golpe, sin cierre ordenado.'),
    op('Un cliente envía un SYN con número de secuencia 700. ¿Qué número de acuse lleva el SYN-ACK del servidor?', ['701', '700', '1400', '699'], 0, 'El acuse indica el siguiente byte esperado, y el SYN cuenta como uno: 700 + 1 = 701.'),
    op('Un receptor TCP recibe correctamente un segmento con secuencia 5000 y 400 bytes de datos. ¿Qué número de acuse devuelve?', ['5400', '5000', '5001', '400'], 0, 'El acuse es la secuencia más los bytes recibidos: 5000 + 400 = 5400, el siguiente byte que espera.'),
    op('¿Qué mecanismo usa TCP para evitar que un emisor rápido sature a un receptor lento?', ['El control de flujo mediante el tamaño de ventana', 'El campo FCS', 'El saludo de tres vías', 'El número de puerto de origen'], 0, 'El receptor anuncia en la ventana cuántos bytes puede aceptar. El FCS detecta errores de trama y el saludo solo abre la conexión.'),
    op('Los segmentos de una descarga llegan desordenados al receptor. ¿Qué campo de TCP permite reordenarlos?', ['El número de secuencia', 'El puerto de destino', 'La bandera SYN', 'El tamaño de ventana'], 0, 'Cada segmento indica el número de su primer byte, y con eso el receptor reconstruye el orden original.'),
    op('¿Cuánto mide el encabezado de UDP?', ['8 bytes', '20 bytes', '4 bytes', '60 bytes'], 0, 'UDP solo lleva cuatro campos: puertos de origen y destino, longitud y suma de comprobación. El de TCP mide 20 bytes como mínimo.'),
    op('¿Por qué DNS usa normalmente UDP para sus consultas?', ['Porque son mensajes cortos y abrir una conexión costaría más que la propia consulta', 'Porque UDP cifra las consultas', 'Porque TCP no admite el puerto 53', 'Porque UDP garantiza la entrega'], 0, 'Una pregunta y una respuesta breves no justifican el saludo de tres vías. UDP no cifra ni garantiza la entrega, y DNS también puede usar TCP en el puerto 53.'),
    op('Una aplicación de videovigilancia transmite video en vivo. Si se pierde un cuadro, se prefiere seguir con el siguiente. ¿Qué protocolo de transporte encaja?', ['UDP', 'TCP', 'ICMP', 'ARP'], 0, 'En tiempo real conviene no esperar retransmisiones. ICMP y ARP no transportan datos de aplicaciones.'),
    op('Una aplicación bancaria debe garantizar que cada orden llegue completa y en orden. ¿Qué protocolo de transporte usa?', ['TCP', 'UDP', 'TFTP', 'NTP'], 0, 'La entrega confiable y ordenada es lo que ofrece TCP. TFTP y NTP son protocolos de aplicación.'),
    op('Un técnico ve en una captura un segmento con la bandera RST como respuesta a un SYN. ¿Qué significa?', ['Que no hay ningún servicio escuchando en ese puerto o la conexión fue rechazada', 'Que la conexión se abrió correctamente', 'Que el servidor pide más datos', 'Que se perdió un acuse'], 0, 'RST rechaza o aborta una conexión. Una apertura correcta se contestaría con SYN-ACK.'),
    op('En la notación `192.168.5.20:8080`, ¿qué representa el número 8080?', ['El puerto', 'El prefijo de red', 'El último octeto de la IP', 'El número de secuencia'], 0, 'Un socket se escribe como dirección IP, dos puntos y puerto. El prefijo de red se escribiría con una barra.'),
    op('Un cliente consulta a un servidor DNS desde su puerto 53211. ¿Qué puertos lleva la **respuesta** del servidor?', ['Origen 53, destino 53211', 'Origen 53211, destino 53', 'Origen 53, destino 53', 'Origen 67, destino 68'], 0, 'En la respuesta los puertos se invierten: el servidor contesta desde su puerto 53 hacia el puerto efímero del cliente. 67 y 68 son los puertos de DHCP.'),
    op('Un técnico analiza esta captura. ¿Qué protocolo de transporte y qué servicio aparecen?', ['UDP, una consulta DNS', 'TCP, una página web', 'UDP, una concesión DHCP', 'TCP, una sesión SSH'], 0, 'El protocolo indicado es UDP y el puerto de destino es el 53, el de DNS. No hay saludo de tres vías porque UDP no lo usa.',
      { codigo: `N.º  Origen              Destino          Protocolo  Información
1    192.168.1.10:53211  192.168.1.1:53   UDP        Standard query A www.ejemplo.com
2    192.168.1.1:53      192.168.1.10:53211  UDP     Standard query response A 203.0.113.20` }),
    op('¿Cuántos mensajes intercambian cliente y servidor para **abrir** una conexión TCP?', ['Tres', 'Dos', 'Cuatro', 'Uno'], 0, 'SYN, SYN-ACK y ACK. Cuatro son los mensajes del cierre normal (dos FIN y dos ACK).'),
    vs('¿Cuáles **dos** características son propias de UDP?', ['No establece conexión', 'Reordena los datos recibidos', 'Tiene poca sobrecarga', 'Retransmite lo que se pierde', 'Usa control de flujo por ventana'], [0, 2], 'UDP envía sin conexión y con un encabezado mínimo. Reordenar, retransmitir y controlar el flujo son funciones de TCP.'),
    vs('¿Cuáles **dos** aplicaciones usan TCP?', ['Transferencia de archivos por FTP', 'Sincronización de hora por NTP', 'Navegación web con HTTPS', 'Voz sobre IP', 'Consultas SNMP'], [0, 2], 'FTP y HTTPS necesitan entrega completa y ordenada. NTP, la voz en vivo y SNMP trabajan sobre UDP.'),
    vs('¿Cuáles **tres** banderas aparecen durante el saludo de tres vías?', ['SYN', 'FIN', 'ACK', 'RST', 'SYN y ACK juntas'], [0, 2, 4], 'El saludo usa SYN, luego SYN con ACK y por último ACK. FIN y RST pertenecen al cierre y al rechazo.'),
    vs('¿Cuáles **dos** datos forman un socket?', ['Una dirección IP', 'Una dirección MAC', 'Un número de puerto', 'Un nombre de usuario', 'Un número de VLAN'], [0, 2], 'Socket = dirección IP + puerto. La MAC es de capa 2 y no forma parte del socket.'),
    vs('¿Cuáles **dos** afirmaciones sobre los puertos dinámicos (49152 a 65535) son correctas?', ['Los asigna el sistema operativo del cliente', 'Están reservados para servidores web', 'Se usan como puerto de origen temporal', 'Solo funcionan con UDP', 'Requieren registro previo'], [0, 2], 'El cliente toma de ese rango un puerto de origen temporal para cada conversación. Valen para TCP y UDP y no se registran.'),
    rel('Relaciona cada bandera TCP con su significado.', [
      ['SYN', 'Solicita abrir la conexión'], ['ACK', 'Confirma lo recibido'], ['FIN', 'Cierra de forma ordenada'], ['RST', 'Corta la conexión de inmediato'],
    ], 'SYN abre, ACK confirma, FIN termina con orden y RST aborta.'),
    rel('Relaciona cada característica con el protocolo al que pertenece.', [
      ['Saludo de tres vías', 'TCP'], ['Encabezado de 8 bytes', 'UDP'], ['Retransmisión de lo perdido', 'TCP'], ['Envío sin conexión previa', 'UDP'],
    ], 'TCP abre conexión y retransmite; UDP envía directamente con un encabezado mínimo.', ['IP']),
    rel('Relaciona cada número de puerto con su rango.', [
      ['443', 'Bien conocidos'], ['3389', 'Registrados'], ['51000', 'Dinámicos o efímeros'],
    ], '443 está por debajo de 1024; 3389 está entre 1024 y 49151; 51000 está por encima de 49151.'),
    ord('Ordena lo que ocurre en una comunicación TCP completa.', ['Saludo de tres vías', 'Envío de datos con acuses de recibo', 'Cierre con FIN y ACK'], 'Primero se abre la conexión, después viajan los datos confirmados y, al final, se cierra de forma ordenada.'),
  ],

  /* ============================================ 6 · Aplicaciones y nube */
  6: [
    op('Un firewall debe permitir que los empleados naveguen por sitios web seguros. ¿Qué puerto de destino hay que abrir?', ['TCP 443', 'TCP 80', 'UDP 53', 'TCP 22'], 0, 'Los sitios seguros usan HTTPS en el puerto 443 sobre TCP. El 80 es HTTP sin cifrar, el 53 es DNS y el 22 es SSH.'),
    op('Tras un cambio en el firewall, los usuarios navegan si escriben la dirección IP de un sitio, pero no si escriben su nombre. ¿Qué puerto se bloqueó por error?', ['53', '80', '443', '123'], 0, 'Falla la resolución de nombres, que usa DNS en el puerto 53. Si se hubiera bloqueado el 80 o el 443, tampoco se navegaría por IP.'),
    op('¿Qué protocolo asigna automáticamente a un equipo su dirección IP, máscara, puerta de enlace y servidor DNS?', ['DHCP', 'DNS', 'NTP', 'SNMP'], 0, 'Entregar la configuración IP es la función de DHCP. DNS solo traduce nombres.'),
    op('¿Qué mensaje envía primero un cliente DHCP al conectarse a la red?', ['Discover', 'Offer', 'Request', 'Acknowledge'], 0, 'El cliente empieza con un Discover por broadcast, porque aún no conoce a ningún servidor. Offer y Acknowledge los envía el servidor.'),
    op('¿Por qué el mensaje DHCP Discover se envía por broadcast?', ['Porque el cliente aún no tiene dirección IP ni conoce la del servidor', 'Porque el broadcast es más rápido', 'Porque DHCP usa TCP', 'Porque el servidor DHCP no tiene dirección MAC'], 0, 'Al arrancar, el cliente no sabe a quién dirigirse, así que pregunta a todos los de su red. DHCP usa UDP.'),
    op('Una computadora con Windows muestra la dirección `169.254.77.3`. ¿Qué indica?', ['Que no recibió respuesta de ningún servidor DHCP', 'Que tiene una dirección pública de Internet', 'Que el DNS está mal configurado', 'Que su tarjeta de red está desactivada'], 0, 'El rango 169.254.0.0/16 se lo asigna el propio equipo cuando DHCP no contesta. Con la tarjeta desactivada no tendría ninguna dirección.'),
    op('¿Qué protocolo debe usar un administrador para acceder a la línea de comandos de un router de forma cifrada?', ['SSH', 'Telnet', 'HTTP', 'TFTP'], 0, 'SSH cifra toda la sesión. Telnet ofrece lo mismo, pero en texto claro.'),
    op('Una auditoría de seguridad encuentra abierto el puerto 23 en varios switches. ¿Qué recomienda?', ['Desactivar Telnet y usar SSH', 'Abrir también el puerto 21', 'Cambiar a HTTP', 'No hacer nada: el puerto 23 es seguro'], 0, 'El 23 es Telnet, que transmite las contraseñas sin cifrar. Su reemplazo seguro es SSH, en el puerto 22.'),
    op('¿Qué protocolo de transferencia de archivos funciona sobre UDP y no pide usuario ni contraseña?', ['TFTP', 'FTP', 'SFTP', 'HTTPS'], 0, 'TFTP es la transferencia mínima, en el puerto 69 sobre UDP. FTP y SFTP autentican al usuario y trabajan sobre TCP.'),
    op('¿En qué puerto escucha SFTP?', ['22', '21', '69', '990'], 0, 'SFTP viaja dentro de SSH y por eso usa el puerto 22. El 21 es el canal de control de FTP y el 69 es TFTP.'),
    op('¿Qué protocolo usa un programa de correo para **enviar** un mensaje al servidor?', ['SMTP', 'IMAP', 'POP3', 'SNMP'], 0, 'SMTP es el protocolo de salida. IMAP y POP3 sirven para leer el buzón.'),
    op('Un usuario configuró su correo con POP3 en la computadora de la oficina y ahora no ve los mensajes antiguos en su teléfono. ¿Por qué?', ['Porque POP3 descargó los mensajes a la computadora y los quitó del servidor', 'Porque POP3 cifra los mensajes', 'Porque el teléfono no admite TCP', 'Porque SMTP los borró'], 0, 'Por defecto, POP3 baja el correo a un equipo y lo elimina del servidor. Con IMAP los mensajes permanecen en el servidor para todos los dispositivos.'),
    op('Los certificados de un servidor empiezan a fallar porque su reloj está tres horas atrasado. ¿Qué protocolo debe revisarse?', ['NTP', 'DNS', 'DHCP', 'FTP'], 0, 'NTP mantiene la hora correcta. Muchos mecanismos de seguridad dependen de que el reloj coincida.'),
    op('Un sistema de monitoreo consulta cada minuto el uso de CPU y el estado de las interfaces de los switches. ¿Qué protocolo usa?', ['SNMP', 'SMTP', 'NTP', 'TFTP'], 0, 'SNMP está diseñado para consultar y administrar dispositivos de red. SMTP, aunque se parece en el nombre, es de correo.'),
    op('¿Qué protocolo permite ver y controlar el escritorio gráfico de un equipo con Windows a distancia?', ['RDP', 'SSH', 'Telnet', 'TFTP'], 0, 'RDP (puerto 3389) da acceso al escritorio completo. SSH y Telnet solo ofrecen línea de comandos.'),
    op('¿Cuál de estas afirmaciones sobre ICMP es correcta?', ['No usa números de puerto: viaja directamente sobre IP', 'Usa el puerto TCP 7', 'Es un protocolo de la capa de aplicación', 'Solo funciona con IPv6'], 0, 'ICMP es un protocolo de la capa de red que acompaña a IP; no se monta sobre TCP ni UDP. Existe para IPv4 y para IPv6.'),
    op('¿Qué aporta HTTPS que HTTP no tiene?', ['Cifrado y verificación de la identidad del servidor mediante un certificado', 'Mayor velocidad de descarga', 'Uso de UDP en lugar de TCP', 'Direcciones IP más cortas'], 0, 'HTTPS añade TLS: confidencialidad, integridad y autenticación del servidor. No es más rápido por sí mismo.'),
    op('Una empresa usa una aplicación de contabilidad a la que entra por el navegador y paga una cuota mensual por usuario. ¿Qué modelo de servicio es?', ['SaaS', 'PaaS', 'IaaS', 'Local'], 0, 'Usar una aplicación terminada a través de Internet es software como servicio.'),
    op('Un equipo de desarrollo quiere publicar su aplicación sin instalar ni actualizar sistemas operativos. ¿Qué modelo de servicio le conviene?', ['PaaS', 'IaaS', 'Local', 'Una red de campus'], 0, 'En PaaS el proveedor administra la plataforma y el cliente solo aporta su código. En IaaS tendrían que mantener el sistema operativo.'),
    op('Un administrador necesita control total del sistema operativo de sus servidores, pero no quiere comprar equipos. ¿Qué modelo de servicio elige?', ['IaaS', 'SaaS', 'PaaS', 'Extranet'], 0, 'IaaS alquila la infraestructura y deja el sistema operativo en manos del cliente. En PaaS y SaaS no hay acceso al sistema operativo.'),
    op('Tres universidades comparten una plataforma de nube creada exclusivamente para ellas. ¿Qué modelo de despliegue es?', ['Comunitaria', 'Pública', 'Privada', 'Híbrida'], 0, 'Varias organizaciones afines que comparten una nube cerrada al público forman una nube comunitaria. Sería privada si fuera de una sola.'),
    op('¿Cuál es un inconveniente de trasladar todos los servicios a la nube pública?', ['Sin conexión a Internet no se puede trabajar', 'Hay que comprar más servidores', 'No se puede acceder desde casa', 'La capacidad no se puede ampliar'], 0, 'La dependencia de la conexión es el punto débil. Las otras opciones describen justo lo contrario de lo que ofrece la nube.'),
    op('Con su proveedor de correo SaaS, una empresa sufre una fuga de datos porque un empleado usaba la contraseña «123456». Según el modelo de responsabilidad compartida, ¿quién falló?', ['El cliente, responsable de sus cuentas y accesos', 'El proveedor, responsable de todo', 'El proveedor de internet', 'El fabricante del navegador'], 0, 'El proveedor asegura la plataforma; las cuentas, contraseñas y permisos de los usuarios son responsabilidad del cliente.'),
    vs('¿Cuáles **dos** protocolos trabajan sobre UDP?', ['DHCP', 'SSH', 'SNMP', 'HTTPS', 'SMTP'], [0, 2], 'DHCP (67 y 68) y SNMP (161) usan UDP. SSH, HTTPS y SMTP usan TCP.'),
    vs('¿Cuáles **dos** protocolos cifran la comunicación?', ['SSH', 'Telnet', 'HTTPS', 'TFTP', 'HTTP'], [0, 2], 'SSH y HTTPS protegen la sesión con cifrado. Telnet, TFTP y HTTP transmiten en texto claro.'),
    vs('¿Cuáles **tres** protocolos están relacionados con el correo electrónico?', ['SMTP', 'SNMP', 'IMAP', 'POP3', 'NTP'], [0, 2, 3], 'SMTP envía; IMAP y POP3 reciben. SNMP es de monitoreo y NTP de sincronización de hora.'),
    vs('¿Cuáles **dos** datos entrega un servidor DHCP a sus clientes?', ['La puerta de enlace predeterminada', 'La dirección MAC', 'El servidor DNS', 'El número de serie', 'El sistema operativo'], [0, 2], 'DHCP entrega dirección IP, máscara, puerta de enlace y servidor DNS. La MAC viene de fábrica en la tarjeta.'),
    vs('¿Cuáles **dos** situaciones describen un servicio local (on-premises)?', ['Los servidores están en un cuarto del edificio de la empresa', 'Se paga por minuto de uso a un proveedor', 'El personal propio hace los respaldos y las actualizaciones', 'La capacidad se amplía en minutos desde un portal', 'El proveedor administra el sistema operativo'], [0, 2], 'En local, la organización es dueña de los equipos y responsable de mantenerlos. Lo demás describe servicios de nube.'),
    rel('Relaciona cada protocolo con su puerto por defecto.', [
      ['SSH', '22'], ['DNS', '53'], ['HTTP', '80'], ['HTTPS', '443'], ['RDP', '3389'],
    ], 'Acceso remoto cifrado en el 22, nombres en el 53, web en 80 y 443, y escritorio remoto en el 3389.', ['23', '110']),
    rel('Relaciona cada modelo de servicio con su descripción.', [
      ['SaaS', 'Se usa una aplicación terminada'], ['PaaS', 'Se sube la aplicación propia a una plataforma administrada'], ['IaaS', 'Se alquilan máquinas virtuales y se instala todo'],
    ], 'De menos a más trabajo para el cliente: SaaS, PaaS e IaaS.', ['Se compran servidores para el edificio']),
    rel('Relaciona cada modelo de despliegue con quién lo usa.', [
      ['Pública', 'Cualquier cliente que la contrate'], ['Privada', 'Una sola organización'], ['Comunitaria', 'Varias organizaciones con necesidades comunes'], ['Híbrida', 'Combina entornos privados y públicos conectados'],
    ], 'La clasificación por despliegue responde a quién puede usar la infraestructura.'),
    ord('Ordena lo que hace una laptop desde que se conecta a la red hasta que muestra una página web segura.', ['Obtiene su configuración IP por DHCP', 'Resuelve el nombre del sitio con DNS', 'Abre una conexión TCP al puerto 443', 'Negocia el cifrado TLS', 'Pide la página con HTTPS'], 'Sin dirección IP no se puede consultar DNS; sin la IP del sitio no se puede abrir la conexión; y la página viaja ya dentro del canal cifrado.'),
  ],
};
